package greeter

import "strings"

// JoinSlug 把多段文本各自 slug 化后用 "/" 串起来；空串与纯空白段被跳过。
func JoinSlug(parts ...string) string {
	slugs := make([]string, 0, len(parts))
	for _, part := range parts {
		if s := Slug(part); s != "" {
			slugs = append(slugs, s)
		}
	}
	return strings.Join(slugs, "/")
}

package greeter

import "testing"

func TestJoinSlug(t *testing.T) {
	cases := []struct {
		in   []string
		want string
	}{
		{[]string{"Hello World", "Big Day"}, "hello-world/big-day"},
		{[]string{"a", "", "b"}, "a/b"},
		{[]string{"a", "   ", "b"}, "a/b"},
	}
	for _, c := range cases {
		if got := JoinSlug(c.in...); got != c.want {
			t.Errorf("JoinSlug(%q) = %q, want %q", c.in, got, c.want)
		}
	}
}
